  const readCalls = [];
  const readyCalls = [];
  const writeCalls = [];
  const ready = [deferred(), deferred()];
  const writes = [deferred(), deferred()];
  let cancelled = 0;
  let released = 0;
  let outputExtraCalls = 0;

  const reader = {
    read() {
      readCalls.push(true);
